//! 48 `RuleContract` implementors: 24 textual (submodules below, one file
//! each) and 24 generated by `define_rules!` in [`generated`] with no
//! textual `impl` line of their own.

pub mod cfg_gated;
pub mod customer_credit_rule;
pub mod deposit_required_rule;
pub mod device_age_rule;
pub mod discount_ceiling_rule;
pub mod generated;
pub mod gross_profit_rule;
pub mod idle_technician_rule;
pub mod invoice_balance_rule;
pub mod label_presence_rule;
pub mod maximum_backlog_rule;
pub mod minimum_stock_rule;
pub mod note_required_rule;
pub mod part_availability_rule;
pub mod part_cost_margin_rule;
pub mod priority_escalation_rule;
pub mod repair_duration_rule;
pub mod revenue_floor_rule;
pub mod rework_limit_rule;
pub mod rush_surcharge_rule;
pub mod schedule_gap_rule;
pub mod signature_required_rule;
pub mod slot_overbooking_rule;
pub mod status_sequence_rule;
pub mod technician_capacity_rule;
pub mod warranty_window_rule;

use crate::contracts::rule_contract::RuleContract;
use once_cell::sync::Lazy;

/// Every rule in the lane: 24 textual implementors, then the 24 generated
/// by `define_rules!`, in the order documented on the issue.
pub static RULES: Lazy<Vec<Box<dyn RuleContract>>> = Lazy::new(|| {
    vec![
        Box::new(minimum_stock_rule::MinimumStockRule),
        Box::new(maximum_backlog_rule::MaximumBacklogRule),
        Box::new(warranty_window_rule::WarrantyWindowRule),
        Box::new(rush_surcharge_rule::RushSurchargeRule),
        Box::new(technician_capacity_rule::TechnicianCapacityRule),
        Box::new(part_availability_rule::PartAvailabilityRule),
        Box::new(invoice_balance_rule::InvoiceBalanceRule),
        Box::new(customer_credit_rule::CustomerCreditRule),
        Box::new(device_age_rule::DeviceAgeRule),
        Box::new(repair_duration_rule::RepairDurationRule),
        Box::new(rework_limit_rule::ReworkLimitRule),
        Box::new(discount_ceiling_rule::DiscountCeilingRule),
        Box::new(deposit_required_rule::DepositRequiredRule),
        Box::new(label_presence_rule::LabelPresenceRule),
        Box::new(note_required_rule::NoteRequiredRule),
        Box::new(signature_required_rule::SignatureRequiredRule),
        Box::new(priority_escalation_rule::PriorityEscalationRule),
        Box::new(status_sequence_rule::StatusSequenceRule),
        Box::new(part_cost_margin_rule::PartCostMarginRule),
        Box::new(revenue_floor_rule::RevenueFloorRule),
        Box::new(gross_profit_rule::GrossProfitRule),
        Box::new(schedule_gap_rule::ScheduleGapRule),
        Box::new(slot_overbooking_rule::SlotOverbookingRule),
        Box::new(idle_technician_rule::IdleTechnicianRule),
        Box::new(generated::DuplicateReferenceRule),
        Box::new(generated::ReferencePrefixRule),
        Box::new(generated::CurrencyConsistencyRule),
        Box::new(generated::RoundingRule),
        Box::new(generated::TaxAppliedRule),
        Box::new(generated::ExportFreshnessRule),
        Box::new(generated::NotificationSentRule),
        Box::new(generated::AuditTrailRule),
        Box::new(generated::CacheTtlRule),
        Box::new(generated::ReportCoverageRule),
        Box::new(generated::MetricRangeRule),
        Box::new(generated::DatasetIntegrityRule),
        Box::new(generated::SeedDeterminismRule),
        Box::new(generated::OrderCountRule),
        Box::new(generated::CustomerCountRule),
        Box::new(generated::PartCountRule),
        Box::new(generated::InvoiceCountRule),
        Box::new(generated::OpenOrderRatioRule),
        Box::new(generated::CompletionRateRule),
        Box::new(generated::AverageTicketRule),
        Box::new(generated::PartsPerOrderRule),
        Box::new(generated::RepeatCustomerRule),
        Box::new(generated::DeviceCategoryRule),
        Box::new(generated::InventoryTurnoverRule),
    ]
});

/// Return-position `impl Trait`: every rule as one iterator, no boxing at
/// the call site.
pub fn rules() -> impl Iterator<Item = &'static dyn RuleContract> {
    RULES.iter().map(|rule| rule.as_ref())
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::dataset::Dataset;

    #[test]
    fn all_48_rules_pass_on_seed() {
        let data = Dataset::seeded();

        assert_eq!(RULES.len(), 48);
        assert!(rules().all(|rule| rule.evaluate(&data)));
    }
}
